from __future__ import annotations

from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Tuple

class TurnoverStage:
    NOTICE_LOGGED = "notice_logged"
    MOVE_OUT_INSPECTED = "move_out_inspected"
    MAINTENANCE_IN_PROGRESS = "maintenance_in_progress"
    DEEP_CLEANING = "deep_cleaning"
    READY_FOR_RELISTING = "ready_for_relisting"

class SLAThresholdHours:
    EMERGENCY = 4
    HIGH = 24
    MEDIUM = 48
    LOW = 96

class RoomTurnoverLifecycleManager:
    VALID_TRANSITIONS = {
        TurnoverStage.NOTICE_LOGGED: [TurnoverStage.MOVE_OUT_INSPECTED],
        TurnoverStage.MOVE_OUT_INSPECTED: [TurnoverStage.MAINTENANCE_IN_PROGRESS, TurnoverStage.DEEP_CLEANING],
        TurnoverStage.MAINTENANCE_IN_PROGRESS: [TurnoverStage.DEEP_CLEANING],
        TurnoverStage.DEEP_CLEANING: [TurnoverStage.READY_FOR_RELISTING],
        TurnoverStage.READY_FOR_RELISTING: [],
    }

    def __init__(self, room_id: str, bed_id: str, current_stage: str = TurnoverStage.NOTICE_LOGGED):
        self.room_id = room_id
        self.bed_id = bed_id
        self.current_stage = current_stage
        self.history: List[Dict[str, Any]] = [
            {"stage": current_stage, "timestamp": datetime.now(timezone.utc).isoformat(), "notes": "Turnover initialized"}
        ]

    def advance_stage(self, next_stage: str, notes: str = "") -> Dict[str, Any]:
        allowed = self.VALID_TRANSITIONS.get(self.current_stage, [])
        if next_stage not in allowed:
            raise ValueError(f"Invalid turnover stage transition from '{self.current_stage}' to '{next_stage}'. Allowed: {allowed}")
        self.current_stage = next_stage
        self.history.append({"stage": next_stage, "timestamp": datetime.now(timezone.utc).isoformat(), "notes": notes})
        return {
            "room_id": self.room_id,
            "bed_id": self.bed_id,
            "current_stage": self.current_stage,
            "history_count": len(self.history),
            "is_complete": self.current_stage == TurnoverStage.READY_FOR_RELISTING,
        }

    def is_ready_for_tenant(self) -> bool:
        return self.current_stage == TurnoverStage.READY_FOR_RELISTING

class TurnoverInspectionChecklist:
    STANDARD_ITEMS = [
        {"item": "door_lock_and_key", "category": "carpentry", "baseline_cost": 450.0},
        {"item": "ceiling_fan_and_regulator", "category": "electrical", "baseline_cost": 350.0},
        {"item": "plumbing_faucet_and_drain", "category": "plumbing", "baseline_cost": 600.0},
        {"item": "wall_paint_and_patches", "category": "civil", "baseline_cost": 1200.0},
        {"item": "mattress_and_bedframe", "category": "furniture", "baseline_cost": 1500.0},
        {"item": "ac_cooling_and_remote", "category": "appliances", "baseline_cost": 850.0},
    ]

    @classmethod
    def evaluate_inspection(cls, inspection_results: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        passed = []
        failed = []
        cost = 0.0
        for std in cls.STANDARD_ITEMS:
            k = std["item"]
            check = inspection_results.get(k, {"status": "pass", "damage_cost": 0.0})
            if check.get("status") == "pass":
                passed.append(k)
            else:
                c = float(check.get("damage_cost", std["baseline_cost"]))
                cost += c
                failed.append({"item": k, "category": std["category"], "estimated_repair_cost": c})
        return {
            "total_items_checked": len(cls.STANDARD_ITEMS),
            "passed_count": len(passed),
            "failed_count": len(failed),
            "pass_rate_pct": round((len(passed) / len(cls.STANDARD_ITEMS)) * 100, 1),
            "total_remedial_cost": round(cost, 2),
            "failed_items": failed,
            "requires_contractor_work_orders": len(failed) > 0,
        }

class VendorSLAComplianceTracker:
    @staticmethod
    def get_max_allowed_hours(severity: str) -> int:
        s = str(severity).lower()
        if "emergency" in s: return SLAThresholdHours.EMERGENCY
        if "high" in s: return SLAThresholdHours.HIGH
        if "medium" in s: return SLAThresholdHours.MEDIUM
        return SLAThresholdHours.LOW

    @classmethod
    def audit_ticket_sla(cls, severity: str, created_at: datetime, resolved_at: Optional[datetime] = None, now: Optional[datetime] = None) -> Dict[str, Any]:
        if not now: now = datetime.now(timezone.utc)
        if created_at.tzinfo is None: created_at = created_at.replace(tzinfo=timezone.utc)
        allowed = cls.get_max_allowed_hours(severity)
        eff = resolved_at if resolved_at else now
        if eff.tzinfo is None: eff = eff.replace(tzinfo=timezone.utc)
        dur = max(0.0, (eff - created_at).total_seconds() / 3600.0)
        breached = dur > allowed
        return {
            "severity": severity,
            "max_allowed_hours": allowed,
            "elapsed_hours": round(dur, 2),
            "is_resolved": resolved_at is not None,
            "is_breached": breached,
            "hours_overdue": round(max(0.0, dur - allowed), 2),
            "status": "breached" if breached else ("completed_on_time" if resolved_at else "within_sla"),
        }

class ContractorScorecardEngine:
    @staticmethod
    def calculate_vendor_score(on_time_ratio: float, rating_avg: float, budget_adherence_ratio: float, rework_rate: float = 0.0) -> Dict[str, Any]:
        c_ontime = max(0.0, min(1.0, on_time_ratio)) * 35.0
        c_rating = max(0.0, min(5.0, rating_avg)) / 5.0 * 30.0
        c_budget = max(0.0, min(1.0, budget_adherence_ratio)) * 25.0
        c_rework = max(0.0, (1.0 - min(1.0, rework_rate))) * 10.0
        tot = round(c_ontime + c_rating + c_budget + c_rework, 1)
        if tot >= 85: tier = "Tier 1 (Preferred / Priority Dispatch)"
        elif tot >= 70: tier = "Tier 2 (Standard / Secondary Dispatch)"
        elif tot >= 50: tier = "Tier 3 (Probation / Under Review)"
        else: tier = "Tier 4 (Blacklisted / De-listed)"
        return {
            "total_score": tot,
            "performance_tier": tier,
            "is_eligible_for_emergency_dispatch": tot >= 75,
        }

