def get_turnover_inspection_benchmark(inspection_id: str) -> Dict[str, Any]:
    for b in TURNOVER_INSPECTION_BENCHMARKS:
        if b["inspection_id"] == inspection_id:
            return b
    return {"inspection_id": inspection_id, "found": False}

